add(S,'evidence-rules','consumer_binding','Proving constitutional claims.',
    'A witness supports only its bound property; changed evidence cannot author changed meaning or permission. Claim owner supplies property/scope, authorized evaluator supplies evidence.',
    ['Apply proof-target exclusion, semantic/evidence/view separation and assurance/fresh-construction conditions at their specific triggers.'], [], ['Claim identity/scope and actual witness/authority.'], ['SPEC_METHOD.proof-target-identity-and-adequacy-stdo-up-001','SPEC_METHOD.semantic-evidence-and-projection-separation-stdo-up-008','SPEC_METHOD.assurance-boundary-congruence-and-method-qualification-stdo-up-022'])
add(S,'proof-target-identity-and-adequacy-stdo-up-001','constraint','Selecting a load-bearing proof witness.',
    'Before choosing evidence bind exact subject/property/basis, witness-to-claim relation, nearest weaker excluded property and falsification condition; otherwise evidence is discovery, not closure proof.',
    ['Packaging/syntax/compile/presence/invocation/local behavior cannot substitute for semantic/authority/installed/release/end-to-end claim because easier to measure.'], [], ['Actual claim, witness relation, excluded weaker property and defeating condition.'], SG)
add(S,'semantic-evidence-and-projection-separation-stdo-up-008','definition_data','Evaluating or projecting a claim and changing its support.',
    {'semantic_basis':'constitutional/accepted-design meaning','evidence_basis':'exact artifacts/events/logs/tests/observations','state_projection':'current derived view from admitted semantic/evidence basis'},
    ['Check verdict currentness and view fidelity; evidence/view change alone does not change meaning.', 'Semantic change re-enters owner and invalidates affected downstream acceptance.'],
    ['Broad digest may conservatively invalidate review without proving every semantic relation changed.'], ['Exact meaning/evidence/view and changed dependencies.'], ['TRANSFORMATION_LIBRARY.faithful-projection','FOUNDATIONS.workspace-and-context'])
add(S,'assurance-boundary-congruence-and-method-qualification-stdo-up-022','constraint','Claiming promotion/closure assurance, mechanical enforcement, generic method sufficiency or derived-guidance native use.',
    'Assurance covers the authoritative composite subject and exact claim population/quantifier; mechanical enforcement requires an executable/reproducible predicate and an observed witness through ordinary assurance, not planned harness presence.',
    ['Generalization needs inference relation, comparable population, counterexample treatment and evidence; later counterevidence invalidates dependent verdicts until superseded/withdrawn/requalified.', 'Generic sufficiency trial uses fresh competent constructor inside declared capability/context/configuration using declared ordinary authority; independent authorized evaluator binds basis/comparison predicate.', 'Withhold material expected/reference outcomes, exemplars/incumbent realization, author memory and ad hoc rescue until frozen construction where earlier exposure compromises reconstructive independence.', 'After freeze compare to mandatory governing semantics; optional reference is non-authoritative, with equivalence only where basis requires it. Subjective similarity, byte/shape equality, determinism or incumbent match is not generic conformance.', 'Post-exposure revision is a declared intervention/new subject, never retroactive pass.', 'Changed guidance uses source-derived permissions/exclusions/invalidators; ordinary actor native use needs entry/context evidence. Integrity/index generation is not fidelity/usability; mechanical/operational claims need executable workload observations.'],
    ['Any lawful alternative may satisfy semantics; out-of-envelope construction cannot indict generic sufficiency.', 'No actor count/type, review-round, engine, prompt or orchestration is prescribed.'], ['Exact composite claim/population, ordinary executable witnesses, frozen constructor exposure/envelope, independent evaluator mandate, source semantics and applicable reference relation.'], SG+['SPEC_METHOD.probabilistic-work-boundary','SPEC_METHOD.reconstruction-litmus'])
add(S,'verification-layers','definition_data','Choosing evidence by layer and requirement kind.',
    {'Requirements':'invariant truth: what must hold','Design':'structural choice: how truth is realized','Scenarios':'concrete end-to-end operational meaning: can composed Product do claimed thing'},
    ['Capability/scenario failures concern actual-vs-claimed behavior, not merely prose consistency; scenario inability exposes unrealized capability meaning.'],
    ['Constraints/governance/verification duties may need different evidence in addition to or instead of end-to-end scenarios.'], ['Requirement kind, actual composed behavior and evidence scope.'])
add(S,'testing-strategy-taxonomy','definition_data','Every executable proof lane and any UAT/live-acceptance claim.',
    {'Design/module conformance':'derives from accepted design/module/IACS/carrier/structural/fail-closed law; unit and some integration/negative tests','UAT/acceptance':'derives from requirement/acceptance/scenario/Product-release claim and runs isolated composed Product via declared installed/deployed/runnable public/control/runtime surfaces','Harnessed sandbox':'full Product path using deterministic/fake/recorded/injected worker results; proves wiring/control/projection/archive','Live sandbox':'full path crosses actual configured external probabilistic worker/tool/service and returns evidence/result/provenance'},
    ['Declare lane authority; ticketed proof follows admitted ticket/triage/cited law, never code precedent.', 'Only sandbox or explicitly equivalent isolated composed-product lane is UAT; unit/helper/module integration alone cannot close user acceptance.', 'Claim depending on live compute requires live proof beyond semantic/unit/module/harnessed green.', 'Map local labels to taxonomy before closure: integration is breadth, unit is design scope, sandbox composed acceptance, live actual external execution, not a live-named view.'],
    ['Runner/speed/breadth do not select authority; Design retains module-derived proof ownership.'], ['Actual proof authority, entry path, worker mode and selected Product claim.'])
add(S,'fixture-and-proof-portability-rule','constraint','Required closure proof, especially unit/semantic/module-design lanes needing external evidence.',
    'Reproduce required lane from declared source boundary with no undeclared home/sibling/local/mutable fixture dependency.',
    ['External evidence uses checked-in minimal fixture, manifest of source/version/acquisition-binding, or lane reclassification as sandbox/reference/optional local instead of required semantic closure.', 'Missing fixture returns governed diagnostic naming authority/lane, not false Product semantic failure.'], [], ['Actual source boundary, fixture declaration/acquisition and proof performance.'], ['FOUNDATIONS.result-algebra'],
    'Missing fixture leaves Product property indeterminate when evidence insufficient, retaining independent counterevidence/scope/basis. Separately proven fixture absence falsifies fixture-available predicate. Keep actual evaluation performance; fixture absence alone is no Product counterexample.')
add(S,'test-authority-rule','constraint','Any live requirement claimed fully proved.',
    'Written traceable testcase authority exists; informal confidence, habit or unlabeled test corpus cannot establish full proof.',
    ['Choose explicit evidence cases suited to requirement truth.'],
    ['Authority may be scenario bundle, ordered sequence, negative/control cases or other written cases.'], ['Requirement-to-written-case trace and evidence.'])
add(S,'scenario-bundle-rule','constraint','Requirement claims meaningful system behavior.',
    'Use scenario bundle or equivalent coherent ordered cases identifying feature/use-case boundary, proving sequence and expected significant-step outcomes, rather than disconnected assertions alone.',
    ['Operational boundaries/actors/controls/outcomes pressure intent/design and identify significant code/control paths.'],
    ['Equivalent ordered testcase forms are permitted; source uses should for bundle selection.'], ['Requirement scenario, actual sequence and outcomes.'])
add(S,'installed-dev-proof-rule','constraint','System has an installable or runnable development form.',
    'Decisive proof exercises installed development version as independent/externalized target, beyond in-place source checks.',
    ['Source/unit checks cannot replace installed-dev system proof.'],
    ['Prefer fresh sandbox/equivalent isolation, built/installed artifact and real declared entry/control/runtime surfaces.'], ['Runnable dev artifact identity, isolation and actual entry-path observations.'])
add(S,'significant-path-coverage-rule','constraint','Proving a selected behavioral claim.',
    'Declare and intentionally exercise every significant path for that behavior; absent declared set prevents assessing coverage and unexercised members leave proof incomplete.',
    ['Include success, rejection, boundary/control, integration/dispatch/transport and recovery/retry/replay where relevant.'],
    ['Exhaustive means meaningful declared paths, not every branch in every file.'], ['Claim-derived meaningful-path set and execution evidence.'])
add(S,'requirement-categories','definition_data','Every live requirement family.',
    {'Capability':'behavior/function/surface to provide','Constraint / Guarantee':'invariant/law/safety/portability/semantic bound','Governance':'lifecycle/authority/visibility/release/operator control','Verification':'tests/evidence/trace/qualification/forensic duties'},
    ['Categorize by owned constitutional truth, not priority or user-facing feature; Design owns structural HOW.', 'Avoid freezing path/file/package choice unless itself constitutional.'],
    ['Not every requirement is a marketed feature; constraints/governance/verification remain WHAT.'], ['Actual requirement meaning and any constitutional mechanism constraint.'])
add(S,'reconstruction-litmus','constraint','Assessing specification sufficiency at selected chain boundary or reusing an accepted relation.',
    'Competent actors can derive conformant Intent from Goals, Product from Intent, Requirements from Product, Design from Requirements and Code from Requirements+Design without hidden major ambiguity; sufficiency does not demand unique output.',
    ['A failed boundary exposes unclear/contradictory/undecomposable governing layer or incomplete design; a produced artifact does not cure hidden major ambiguity.', 'Reuse exact current accepted basis/evidence only after applicability/invalidator checks; new material counterexamples challenge affected relation.', 'Retain Design-owned view coverage/material-change gate.'],
    ['Different lawful designs/codebases can conform.', 'A correct reconstruction route need not execute each use, grants no restart, and selected local claim does not require full Product rebuild or recreating unchanged accepted views.'], ['Declared competence, authoritative upstream meaning, actual derivation evidence and current accepted relation.'], ['SPEC_METHOD.ambiguity-governance-rule','FOUNDATIONS.workspace-and-context'])
add(S,'design-rule','constraint','Choosing concrete realization of required control/delivery surfaces.',
    'Requirements own existence/obligations; Design chooses stack/carrier/runtime/topology unless already constitutionally constrained.',
    ['Do not hardcode file placement/technology in requirements without constitutional necessity, including agent bootstrap/control realization.'],
    ['Constitution may constrain bare axioms/canonical-method routing while Design selects documents, blocks, compiled artifacts or lawful alternative.'], ['Governing requirement and actual constitutional necessity of mechanism.'])
add(S,'renewal-path','constraint','A real scenario/deployment/review/use case exposes a current-model gap.',
    'Use concrete gap analysis to distinguish missing implementation from constitutional insufficiency; constitutional pressure produces Goals/Intent repricing and forward Product/requirements/design/realization derivation.',
    ['New Intent requires concrete use-case gap, not abstract speculation or coding pressure.', 'Maintain directional authority through cumulative iteration and repeated realization/repricing.'],
    ['Implementation/test/replay/scenario gaps can feed the same loop.'], ['Concrete use-case pressure, gap classification and owner repricing.'])
add(S,'trace-closure-and-anti-drift-rule','consumer_binding','Maintaining constitutional closure over realized behavior.',
    'Every live obligation has an owning realization or explicit unresolved/deferred relation; historical evidence cannot alter current authority.',
    ['Apply local trace metadata, supersession/withdrawal and lifecycle/category rules without treating their labels as verdicts.'],
    ['Product and Design retain meaning/structure decisions; default scaffold does not decide them.'], ['Current obligation/realization trace and authority.'], ['TRANSFORMATION_LIBRARY.contract-application'])
add(S,'ownership','constraint','Live requirement families and ADR/design records.',
    'Every live requirement family maps to one or more owning design decisions, and every ADR/design record explicitly states Implements: its governing requirements.',
    [], [], ['Live requirement set and design trace metadata.'])
add(S,'downstream-closure','constraint','Live requirements and shipping behavior/tests.',
    'Every live requirement is realized through design/code/tests or honestly explicitly deferred; every shipping behavior/test traces to live requirements and authorizing design.',
    ['Do not retain free-floating intent or hidden ungoverned Product behavior, even if it works.'],
    ['Explicit honest deferment is a lawful alternative to realized closure, not a completion claim.'], ['Current live set, actual realization trace and explicit deferments.'])
add(S,'drift-signals','definition_data','Diagnosing constitutional/realization drift.',
    {'unowned requirement or ungrounded design':'missing constitutional/design authority','unrecorded deferment or code without owner':'trace drift','shipping behavior/test without requirement+design':'hidden ungoverned Product','tests of habit':'preserved drift','persistent observed delta':'wrong code or stale governing stack, diagnosis still required','capability without scenario':'unverified operational meaning','wrong requirement category':'misclassification','in-place live-law correction':'corrupted constitutional history','real gap inexpressible in requirements':'constitutional renewal, not code hack'},
    ['Trace closure governs behavior, beyond document completeness.'], [], ['Actual current trace, observations, tests, lifecycle and use-case gap.'])
add(S,'live-surface-immutability','constraint','Published live constitutional domain artifact, contrasted with mutable implementation surfaces.',
    'Live domain artifacts are immutable in place: errors are superseded by new version or withdrawn/deleted; history remains in version control/events where present/superseded artifacts.',
    ['Retire superseded transitional/scaffold/fallback paths; any retained responsibility meets Core Migration retention law.'],
    ['Mutable engine/design/tests/tooling can be aggressively refactored.', 'No requirement to ship shims forever; authorized supersession/withdrawal is allowed.'], ['Artifact standing, published history and owning replacement/retention authority.'], ['SPEC_METHOD.closure-criterion'])
add(S,'fundamental-migration-rule','constraint','Intentionally selected new constitutional branch/version/methodology basis abandoning prior shape.',
    'Prior constitution and sideways implementation become source/reference material, not live authority; nothing carries by default and every retained statement/choice/implementation is explicitly re-adopted at correct layer.',
    ['Declare migration line, establish fresh method/Goals/Intent/Product/requirements/design and move old implementation sideways as needed.', 'Classify inherited constitutional material adopted/superseded/deferred/orphaned; inherited module/interface/carrier/view/proof is carry_across, redundant or rewrite before reuse.', 'carry_across means intentional re-adoption, not copying by default; absence means not yet adopted.', 'Re-derive design/code from new authority; direct runtime/view/prompt/proof/review dependence on sideways line is bridge debt, and proxy partial imitation cannot close.'],
    ['Authorized migration may zero inherited constitutional surfaces and use old code/design as reference; this creates a new surface rather than silently mutating old history.'], ['Actual selected migration authority, old/new boundaries and explicit per-item adoption/classification.'], ['SPEC_METHOD.constitutional-migration-options'])
add(S,'transformation-wave-rule','constraint','Refactor/migration in flight or landing in declared affected scope.',
    'In-flight mixed implementation exists only below current break as non-authoritative plumbing; named bounded scaffolds/adapters stay outside acceptance and cannot become competing truth for same subject.',
    ['On landing only new operative path remains in affected scope; prior path survives in history, not stable mixed authority.', 'Retained compatibility is named current behavior, justified in specification, bounded and intentionally tested; otherwise delete superseded paths.'],
    ['Explicit deterministic non-overlapping Product/compatibility scopes may coexist during visibly open migration.'], ['Current break/acceptance path, scope/routing, scaffold disposition and Product compatibility authority.'])
add(S,'legacy-classification-rule','definition_data','Every inherited or legacy requirement.',
    {'Deferred':'retained explicit not-yet-operative/realized obligation; honest deferment, no closure claim','Superseded':'newer owner/decision; add Implements/Supersedes to governing design','Active':'current law; create/update owning design','Orphaned':'outside intended system; remove or explicitly supersede'},
    ['Nothing live remains unclassified.'], [], ['Inherited requirement meaning, owner and actual disposition.'])
add(S,'requirement-classification-rules','constraint','Every live requirement family header.',
    'Explicit independent Status (Active/Deferred/Superseded/Orphaned) and Category (Capability/Constraint-Guarantee/Governance/Verification) describe lifecycle and truth kind respectively; either missing makes classification incomplete.',
    ['Do not infer category from status or status from category.'], [], ['Requirement header and actual lifecycle/semantic role.'])
add(S,'specification-surface-rule','constraint','Writing active specification or closing a downstream artifact in an affected span.',
    'Goals orient wave, Intent direction, Product current decomposable/lifecycle-aware WHAT, Requirements stable obligations/acceptance/lifecycle-or-gap, Design structural HOW and ADRs design memory; maintain present current law without dead or rival layers.',
    ['Goals cannot substitute requirements; Intent avoids optional mechanism unless constitutional; Product is not release notes; ADRs are not requirements.', 'Delete/supersede/move dead law to commentary; migration does not justify stale law.', 'Version labels only for immutable release facts, selector bindings or clearly historical/superseded material, not recency branding.', 'Closure requires clear class, lawful re-entry, derivable downstream layers and congruent active Intent/Product/requirements/design/qualification across affected span.'], [], ['Current authoritative span, lifecycle/acceptance obligations and actual changed scope.'])
add(S,'bootstrap-rule','constraint','Bootstrapping/adopting an STDO-defined Product or replacing its requirement surface.',
    'Start with exact-cut PRODUCT_DEFINITION_TEMPLATE.json at stdo_default.json or stdo_<label>.json; bind current Product layout, complete immutable basis and actual WHAT/HOW/work authority without duplicating rival sources.',
    ['Install manager, resolve discovery and explicitly select/install complete RC with manifest; assign stable mutable-definition identity/source/context distinct from released identities.', 'Bind repository/nonoperative selector/exact URI+digest, additional constitution and basis-qualified entrypoints; establish five sufficiency dimensions.', 'Bind portable source-relative bootstrap targets; preflight and manage marker blocks only; explicitly bind/empty local axioms/overrides/disambiguations.', 'Bind at least one accepted collective frame basis with authority/scope; confirm current Goals and derive/confirm Intent/Product.', 'Gather/classify/bind sole live requirements; at least one tenant root/design/implementation and shared realization law where applicable; Goals/ticket lanes/comments/optional sprint.', 'Bind every known composition target identity, relation authority and nonempty contracts.', 'Validate shape, assert URI syntax, sync/verify exact install and resolve identities/composition/sufficiency/authority.', 'Do not create competing local methodology root or treat mutable/partial method as operative release; method-source edits author only future candidate.'],
    ['Template paths are defaults; existing arbitrary/nested/multiple-definition layouts need no move/rename/duplicate.', 'Explicitly bound verified exact local method copy is lawful, though shared store is default.', 'Complete requirements tree unnecessary day zero; legitimate inputs may include Goals/Intent/Product, requirements, standards/policy, prior versions and migration/repricing material.'], ['Exact selected release/template/manifest, Product definition/source boundary, current authorities, admitted frames, tenant identities and composition set.'], ['SPEC_METHOD.shared-installed-release-basis-and-toolchain-manager','SPEC_METHOD.constitutional-set-sufficiency','SPEC_METHOD.recursive-discovery-and-explicit-composition'])
add(S,'method','constraint','Substantive intake, feature change, bootstrap/repricing or concrete use-case gap.',
    'Triage/classify/re-enter and identify affected consistent span before implementation/repricing/release. Change only affected Goals/Intent/Product; decompose requirements, lawful design, scenarios/evidence, realization and observation while preserving reconstruction and ambiguity governance.',
    ['When Design Method applies, co-evolution requires its co_evolution_admissible(B); otherwise accept smallest causally closed design set before retained code establishes unresolved/contradictory/non-equivalent relation.', 'Without Design Method, co-evolution allowed only with no unresolved material design decision; otherwise accept affected design before retained code establishes it. Reconcile design/code/tests before promotion/closure.', 'Bootstrap resolves definition/exact install/entrypoint/Goals, derives Intent/Product, gathers/classifies sole requirement authority (individual/families), then design/code; record major ambiguity first.', 'Use-case gap is triaged first, then scenario is first substantive artifact; distinguish implementation gap from constitutional insufficiency, repricing wave/Intent and downstream owners when constitutional.', 'Every bug/test/release/operator intake follows same gate.'],
    ['Prefer declarative problem/acceptance before imperative mechanism; ADR is one design form.', 'Unchanged upstream layers need no invented revision.'], ['Current intake/class, upstream truth, applicable design co-evolution conditions, scenario gap and actual admitted evidence.'], ['SPEC_METHOD.universal-intake-triage','SPEC_METHOD.ambiguity-governance-rule','SPEC_METHOD.reconstruction-litmus'])
add(S,'adr-conventions','constraint','Creating or maintaining an ADR.',
    'Each decision-boundary ADR explicitly records Status active/superseded/retired, Implements REQ IDs, Derives from Intent/strategy, Supersedes, successor when superseded and retained special case when applicable.',
    ['Choose decision boundary by design choice making acceptance criteria true, not one ADR per requirement file.', 'Name requirement-specified operational mechanism; event-taxonomy expansion immediately reprices event-contract ADR so event semantics does not become rival constitution.'], [], ['Actual decision scope, requirement mechanism/taxonomy and predecessor/successor relations.'])
add(S,'adr-folder-convention','constraint','Locating/naming ADRs under a bound design authority.',
    'Place ADR at nearest owning design surface: tenant design, shared how.common or project-local design. Default adrs directory and tenant path shapes do not override Product bindings.',
    ['Never place ADR authority in comments/generated views/runtime archives/requirement folders.', 'Use ADR-<local-id>-short-slug.md with local ID unique in owning adrs directory; registry remains read model.'],
    ['Numeric IDs default; existing namespace-prefixed IDs allowed.', 'Capability-family/variant and single-label tenant paths both conform; family/variant is recommended without migration mandate.', 'REGISTRY.md is recommended, not required; adrs physical directory is default not mandatory repository location.'], ['Bound tenant/common/project design owner and local naming namespace.'])
